  "lre.hello": true,
  "lre.state.resync": true,
  "lre.action": true,
  "lre.chip": true,
  "lre.view.open": true,
  "lre.fix": true,
  "lre.edit": true,
  "lre.gm": true,
  "lre.marker": true,
  "lre.keep": true,
  "lre.settings.get": true,
  "lre.settings.set": true,
  "lre.editor": true,
  "lre.world": true,
  "lre.ui": true,
  "lre.map": true,
  "lre.job": true,
  "lre.lore": true,
  "lre.studio": true,
  "lre.preset": true
